"""Package the exact S01 audition files, verify decoding, and request scoped reviews."""
from pathlib import Path
import hashlib, json, subprocess, sys
ROOT=Path(__file__).resolve().parents[1];WORK=ROOT.parents[3];OUT=ROOT/'artifacts/staging-v001'
sys.path.insert(0,str(WORK/'experiments/001_heavy_box'))
from journal import append_event
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def run(args):return subprocess.run(args,check=True,capture_output=True,text=True)
checks=[]
for variant,folder in [('A','audio-A-v002'),('B','audio-B')]:
    target=OUT/f's01-sound-{variant}.mp4'
    if not target.exists(): run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(OUT/'s01-picture-v002.mp4'),'-i',str(OUT/folder/'mix-premaster.wav'),'-map','0:v:0','-map','1:a:0','-c:v','copy','-af','volume=7dB','-c:a','aac','-b:a','192k','-ar','48000','-movflags','+faststart',str(target)])
    probe=json.loads(run(['ffprobe','-v','error','-count_frames','-show_streams','-show_format','-of','json',str(target)]).stdout)
    v=next(s for s in probe['streams'] if s['codec_type']=='video');a=next(s for s in probe['streams'] if s['codec_type']=='audio')
    assert (v['width'],v['height'],int(v['nb_read_frames']),v['avg_frame_rate'])==(960,540,192,'24/1')
    assert a['sample_rate']=='48000' and a['channels']==2 and abs(float(probe['format']['duration'])-8)<.05
    run(['ffmpeg','-v','error','-i',str(target),'-f','null','-'])
    measure=run(['ffmpeg','-hide_banner','-i',str(target),'-af','loudnorm=I=-20:TP=-1:LRA=11:print_format=json','-f','null','-']).stderr
    levels=json.JSONDecoder().raw_decode(measure[measure.rfind('{'):])[0];assert float(levels['input_tp'])<-1
    checks.append({'file':target.name,'sha256':sha(target),'frames':192,'duration':8,'dimensions':[960,540],'audio_channels':2,'audio_hz':48000,'full_decode':'passed','loudness_lufs':float(levels['input_i']),'true_peak_dbtp':float(levels['input_tp'])})
# Same foreground gain for A and B; isolate crowd at its actual mix level.
run(['ffmpeg','-hide_banner','-loglevel','error','-i',str(OUT/'audio-A-v002/stems/ambience.wav'),'-af','volume=6dB','-c:a','pcm_s16le',str(OUT/'crowd-isolated.wav')])
(OUT/'encoded-checks.json').write_text(json.dumps({'candidates':checks,'listening':'Not performed by agent; user audition pending','mix_matching':'Same dialogue and effects at identical gain; variants differ only in recorded crowd. Numerical loudness is not a listening judgment.'},indent=2)+'\n')
style={'version':1,'id':'samtoons-reference-v001','selection':'User supplied 442oons reference and selected this storyline; no catalogue substitution','source':'https://www.youtube.com/watch?v=g3oku3-4-2A','quality_targets':['Original recognizable caricatures','Expressive faces and visible hands','Connected neck, limbs and props','Clean outline and flat kit/environment fills','Readable wide and close staging at viewing size'],'current_scope':'S01 Haaland and Maresca staging; generated illustrated heads, native editable body/set/props','files':{}}
for rel in ['assets/benchmark-v001.md','assets/reference-board.jpg','assets/production-context.md','assets/art-v001/haaland-maresca-heads.png','assets/art-v001/generation-prompt.txt']:
    style['files'][rel]={'sha256':sha(ROOT/rel)}
style['art_provenance']={'generator':'Built-in imagegen','generated_original':'Original facial artwork; source photos and 442oons board used as references, not export pixels','source_references':['research/visual-references/haaland-celebration.png','research/visual-references/maresca-club-portrait.jpg'],'portrait_source':'https://www.mancity.com/news/mens/enzo-maresca-first-day-back-as-manchester-city-manager-63918337','source_credit':'Manchester City official gallery; reference only','limits':'Two views per character; not an approved reusable cast or final lip-sync system'}
(ROOT/'assets/style-selection.json').write_text(json.dumps(style,indent=2)+'\n')
append_event(ROOT,stage='S01/staging-development',status='completed',reviewer='assistant',intent='Make the selected film’s first staging and sound decision concrete',method='Original generated facial art, visible native Blender construction, live hand-control check, streamed eight-second render, shared event-resolved audio and exact encoded checks',result='Original render exposed ENZO before the punchline. Revision 002 conceals the badge wording until frame 114. Wide/close and adjacent reveal frames inspected. Limbs follow hand targets. 192-frame encoded candidates decode. Normal-speed agent listening was not performed; final voices remain placeholders. No full-film completion or creative acceptance claimed.',inputs=['storyline-v001.md','production.json','assets/style-selection.json','scripts/build_staging.py','scripts/render_staging.py','scripts/prepare_staging.py'],outputs=['artifacts/staging-v001/s01-morning-pep-v002.blend','artifacts/staging-v001/native-checks.json','artifacts/staging-v001/render-checks-v002.json','artifacts/staging-v001/encoded-checks.json'])
append_event(ROOT,stage='checkpoint/staging-v001/staging',status='pending_review',intent='Review S01 character design and the greeting/badge staging before detailed animation',method='Native wide/close frames and the eight-second S01 blocking clip, beside the chosen benchmark; cast/role map in selected storyline',result='Presented review candidates. User decision pending. Scope is S01 and this character/art direction; other football shots still require staging and contact inspection.',inputs=['storyline-v001.md','brief.md','assets/style-selection.json','assets/reference-board.jpg','assets/art-v001/haaland-maresca-heads.png'],outputs=['artifacts/staging-v001/s01-morning-pep-v002.blend','artifacts/staging-v001/s01-picture-v002.mp4','artifacts/staging-v001/v002-frame-070.png','artifacts/staging-v001/v002-frame-135.png','artifacts/staging-v001/review.md'])
append_event(ROOT,stage='checkpoint/staging-v001/sound',status='pending_review',intent='Audition crowd and graphic effects in context without silently accepting temporary voices',method='A includes recorded crowd with a gap for the badge; B keeps the same temporary voice and effects without crowd; isolated crowd available',result='User has playable alternatives at matched foreground gain. No agent hearing or final voice approval is claimed. Selection can establish crowd/effect direction only; later football impacts, vocal performances, music and full-film mixing remain to audition.',inputs=['artifacts/staging-v001/audio-plan-A.json','artifacts/staging-v001/audio-plan-B.json','assets/audio-v001/crowd-bed.wav','assets/audio-v001/head-servo.wav','assets/audio-v001/badge-pop.wav','assets/audio-v001/morning-pep-temp.wav'],outputs=['artifacts/staging-v001/s01-sound-A.mp4','artifacts/staging-v001/s01-sound-B.mp4','artifacts/staging-v001/crowd-isolated.wav','artifacts/staging-v001/encoded-checks.json'])
print(json.dumps(checks,indent=2))
